export const EARTH_LAND_RINGS: readonly (readonly LonLat[])[] = RING_COORDINATES.map((ring) => {
  const points: LonLat[] = []
  for (let index = 0; index < ring.length; index += 2) {
    points.push({ lon: ring[index], lat: ring[index + 1] })
  }
  return points
})

